// Hidden native shader regression probe. Compile with -Igame and the project SDL SDK.
#define GL_SILENCE_DEPRECATION
#include <SDL.h>
#include <OpenGL/gl.h>
#include <OpenGL/glext.h>
#include <OpenGL/glu.h>
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <cstring>
#include <vector>
#include <string>
#include "screen_reflections_glsl.h"
const int W=768,H=576;
void die(const char*m){fprintf(stderr,"%s\n",m);exit(1);}
GLuint shader(GLenum t,const std::string&s){GLuint h=glCreateShader(t);const char*p=s.c_str();glShaderSource(h,1,&p,0);glCompileShader(h);GLint ok;glGetShaderiv(h,GL_COMPILE_STATUS,&ok);if(!ok){char l[8192];glGetShaderInfoLog(h,sizeof l,0,l);die(l);}return h;}
void inv(const float*m,float*out){double a[4][8];for(int r=0;r<4;r++)for(int c=0;c<8;c++)a[r][c]=c<4?m[c*4+r]:(c-4==r);for(int c=0;c<4;c++){int q=c;for(int r=c+1;r<4;r++)if(fabs(a[r][c])>fabs(a[q][c]))q=r;for(int j=0;j<8;j++)std::swap(a[c][j],a[q][j]);double d=a[c][c];for(int j=0;j<8;j++)a[c][j]/=d;for(int r=0;r<4;r++)if(r!=c){double f=a[r][c];for(int j=0;j<8;j++)a[r][j]-=f*a[c][j];}}for(int r=0;r<4;r++)for(int c=0;c<4;c++)out[c*4+r]=a[r][c+4];}
void panel(float x,float z,float width,float height){glBegin(GL_QUADS);glVertex3f(x-width,0,z);glVertex3f(x+width,0,z);glVertex3f(x+width,height,z);glVertex3f(x-width,height,z);glEnd();}
void ppm(const std::string&path,const std::vector<float>&pix){FILE*f=fopen(path.c_str(),"wb");fprintf(f,"P6\n%d %d\n255\n",W,H);for(int y=H-1;y>=0;y--)for(int x=0;x<W;x++)for(int c=0;c<3;c++){float a=fmax(0,pix[(y*W+x)*4+c]);unsigned char q=255*pow(a/(1+a),1/2.2);fwrite(&q,1,1,f);}fclose(f);}
int main(int argc,char**argv){if(argc!=2)die("output folder");SDL_SetHint("MAC_BACKGROUND_APP","1");if(SDL_Init(SDL_INIT_VIDEO))die(SDL_GetError());SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,2);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION,1);SDL_Window*w=SDL_CreateWindow("hidden material reflection probe",0,0,W,H,SDL_WINDOW_OPENGL|SDL_WINDOW_HIDDEN);if(!w)die(SDL_GetError());SDL_GLContext ctx=SDL_GL_CreateContext(w);if(!ctx)die(SDL_GetError());
GLuint scene,depth,target,fbo;glGenTextures(1,&scene);glGenTextures(1,&depth);glGenTextures(1,&target);glGenFramebuffersEXT(1,&fbo);glBindFramebufferEXT(GL_FRAMEBUFFER_EXT,fbo);for(GLuint t:{scene,target,depth}){glBindTexture(GL_TEXTURE_2D,t);bool d=t==depth;glTexImage2D(GL_TEXTURE_2D,0,d?GL_DEPTH_COMPONENT24:GL_RGBA16F_ARB,W,H,0,d?GL_DEPTH_COMPONENT:GL_RGBA,GL_FLOAT,0);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,d?GL_NEAREST:GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,d?GL_NEAREST:GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);}
glFramebufferTexture2DEXT(GL_FRAMEBUFFER_EXT,GL_DEPTH_ATTACHMENT_EXT,GL_TEXTURE_2D,depth,0);glDrawBuffer(GL_COLOR_ATTACHMENT0_EXT);glReadBuffer(GL_COLOR_ATTACHMENT0_EXT);
std::string vs="#version 120\nvarying vec2 uv;void main(){uv=gl_MultiTexCoord0.xy;gl_Position=gl_Vertex;}";
std::string fs="#version 120\n#extension GL_ARB_shader_texture_lod : enable\nvarying vec2 uv;uniform float probeRough;\n";fs+=CNC3D_SCREEN_REFLECTIONS_GLSL;fs+="void main(){float z=texture2D(uSSRDepth,uv).r;vec3 P=ssr_world(uv,z);if(z>.99999||abs(P.y)>.005){gl_FragColor=vec4(0);return;}vec4 h=ssr_radiance(P,vec3(0,1,0),normalize(uSSREye-P),probeRough);gl_FragColor=vec4(h.rgb*h.a,1);}";
GLuint prog=glCreateProgram();glAttachShader(prog,shader(GL_VERTEX_SHADER,vs));glAttachShader(prog,shader(GL_FRAGMENT_SHADER,fs));glLinkProgram(prog);GLint linked;glGetProgramiv(prog,GL_LINK_STATUS,&linked);if(!linked)die("link");
FILE*record=fopen((std::string(argv[1])+"/probe.csv").c_str(),"w");fprintf(record,"case,roughness,energy,max,centroid_x,spread_x,pixels\n");
for(int camera=0;camera<2;camera++)for(int mode=0;mode<6;mode++){
float rough=mode==0?.12f:mode==1?.4f:mode==2?.65f:.4f;bool off=mode==3,block=mode==5;float shift=mode==4?.8f:0;
glUseProgram(0);glActiveTexture(GL_TEXTURE0);glBindTexture(GL_TEXTURE_2D,0);glActiveTexture(GL_TEXTURE1);glBindTexture(GL_TEXTURE_2D,0);glActiveTexture(GL_TEXTURE0);glBindFramebufferEXT(GL_FRAMEBUFFER_EXT,fbo);glFramebufferTexture2DEXT(GL_FRAMEBUFFER_EXT,GL_COLOR_ATTACHMENT0_EXT,GL_TEXTURE_2D,scene,0);glFramebufferTexture2DEXT(GL_FRAMEBUFFER_EXT,GL_DEPTH_ATTACHMENT_EXT,GL_TEXTURE_2D,depth,0);if(glCheckFramebufferStatusEXT(GL_FRAMEBUFFER_EXT)!=GL_FRAMEBUFFER_COMPLETE_EXT)die("scene FBO");glViewport(0,0,W,H);glClearColor(0,0,0,1);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);glEnable(GL_DEPTH_TEST);glDepthMask(GL_TRUE);glMatrixMode(GL_PROJECTION);glLoadIdentity();if(camera)gluPerspective(45,double(W)/H,.1,30);else glOrtho(-3.6,3.6,-2.7,2.7,.1,30);float pr[16],mv[16],vp[16]={},iv[16];glGetFloatv(GL_PROJECTION_MATRIX,pr);glMatrixMode(GL_MODELVIEW);glLoadIdentity();gluLookAt(0,3,5,0,0,0,0,1,0);glGetFloatv(GL_MODELVIEW_MATRIX,mv);for(int c=0;c<4;c++)for(int r=0;r<4;r++)for(int k=0;k<4;k++)vp[c*4+r]+=pr[k*4+r]*mv[c*4+k];inv(vp,iv);
glColor3f(.005,.005,.005);glBegin(GL_QUADS);glVertex3f(-3,0,-3);glVertex3f(-3,0,3);glVertex3f(3,0,3);glVertex3f(3,0,-3);glEnd();glColor3f(off?0:20,off?0:.2,off?0:.05);panel(shift,-1,.14,1.3);if(block){glColor3f(0,0,0);panel(0,-.4,1,1.4);}std::vector<float> pix(W*H*4);if(mode==1){glReadPixels(0,0,W,H,GL_RGBA,GL_FLOAT,pix.data());ppm(std::string(argv[1])+"/scene-"+std::to_string(camera)+".ppm",pix);}
glBindTexture(GL_TEXTURE_2D,scene);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_LINEAR_MIPMAP_LINEAR);glGenerateMipmapEXT(GL_TEXTURE_2D);glFramebufferTexture2DEXT(GL_FRAMEBUFFER_EXT,GL_COLOR_ATTACHMENT0_EXT,GL_TEXTURE_2D,target,0);glFramebufferTexture2DEXT(GL_FRAMEBUFFER_EXT,GL_DEPTH_ATTACHMENT_EXT,GL_TEXTURE_2D,0,0);glDisable(GL_DEPTH_TEST);glUseProgram(prog);auto loc=[&](const char*s){return glGetUniformLocation(prog,s);};glUniform1i(loc("uSSRScene"),0);glUniform1i(loc("uSSRDepth"),1);glUniform1i(loc("uSSROn"),1);glUniform1i(loc("uSSRLinear"),1);glUniform2f(loc("uSSRSize"),W,H);glUniform3f(loc("uSSREye"),0,3,5);float n=sqrtf(34);glUniform3f(loc("uSSRForward"),0,-3/n,-5/n);glUniformMatrix4fv(loc("uSSRVP"),1,0,vp);glUniformMatrix4fv(loc("uSSRInvVP"),1,0,iv);glUniform1f(loc("probeRough"),rough);glActiveTexture(GL_TEXTURE1);glBindTexture(GL_TEXTURE_2D,depth);glActiveTexture(GL_TEXTURE0);glBindTexture(GL_TEXTURE_2D,scene);glBegin(GL_QUADS);glTexCoord2f(0,0);glVertex2f(-1,-1);glTexCoord2f(1,0);glVertex2f(1,-1);glTexCoord2f(1,1);glVertex2f(1,1);glTexCoord2f(0,1);glVertex2f(-1,1);glEnd();glReadPixels(0,0,W,H,GL_RGBA,GL_FLOAT,pix.data());if(glGetError()!=GL_NO_ERROR)die("GL error");std::string name=(camera?"perspective-":"orthographic-")+std::to_string(mode);ppm(std::string(argv[1])+"/"+name+".ppm",pix);double energy=0,xsum=0,x2sum=0,max=0;int count=0;for(int y=0;y<H;y++)for(int x=0;x<W;x++){double v=fmax(0,pix[(y*W+x)*4]-pix[(y*W+x)*4+1]);energy+=v;xsum+=v*x;x2sum+=v*x*x;max=fmax(max,v);if(v>.01)count++;}fprintf(record,"%s,%.3f,%.6f,%.6f,%.3f,%.3f,%d\n",name.c_str(),rough,energy,max,xsum/fmax(energy,1e-9),sqrt(fmax(0,x2sum/fmax(energy,1e-9)-pow(xsum/fmax(energy,1e-9),2))),count);fflush(record);
}fclose(record);printf("SSR_PROBE_PASS\n");SDL_GL_DeleteContext(ctx);SDL_DestroyWindow(w);SDL_Quit();}
